export const SPORT_ICON_VIEWBOX = 100;

export const ICON_GROUPS = ['ball', 'combat', 'gym', 'gymnastics', 'water', 'lift', 'target', 'winter', 'racquet', 'track', 'run', 'swim', 'cycle', 'mind', 'dance', 'team', 'walk', 'horse', 'para', 'climb', 'air', 'board'];

export const SPORT_ICONS = ICON_ROWS.map(([id, name, group, d]) => ({ id, name, group, d }));

const BY_ID = Object.fromEntries(SPORT_ICONS.map((icon) => [icon.id, icon]));

/** One icon by id, or null for an id that is not in the set. */
export const getSportIcon = (id) => BY_ID[id] || null;

/** Every icon of one group, in set order. */
export const iconsInGroup = (group) => SPORT_ICONS.filter((icon) => icon.group === group);
